export const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export const size=value=>value>=1073741824?(value/1073741824).toFixed(2)+' GB':value>=1048576?(value/1048576).toFixed(1)+' MB':value>=1024?(value/1024).toFixed(1)+' KB':Number(value||0)+' B';
export const number=value=>Number(value||0).toLocaleString('zh-CN');
export function date(value){if(!value||!Number.isFinite(Date.parse(value)))return '暂无记录';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(value));}
export const uptime=seconds=>seconds>=86400?Math.floor(seconds/86400)+' 天 '+Math.floor(seconds%86400/3600)+' 小时':seconds>=3600?Math.floor(seconds/3600)+' 小时 '+Math.floor(seconds%3600/60)+' 分钟':Math.floor(seconds/60)+' 分钟';
export const providerName=id=>({deepseek:'DeepSeek',cn:'RunningHub 中国站',ai:'RunningHub 国际站',auto:'自动分配'}[id]||id||'—');
const statusName=id=>({planning:'准备中',submitting:'正在提交',queued:'排队中',running:'生成中',succeeded:'已完成',failed:'失败',unknown:'提交待核对',fallback:'使用备用封面',uploading:'上传中'}[id]||id);
export const badge=(text,tone='muted')=>'<span class="badge '+tone+'">'+esc(text)+'</span>';
const statusBadge=status=>badge(statusName(status),status==='succeeded'?'good':['failed','unknown'].includes(status)?'error':status==='fallback'?'warn':'muted');
const categoryName=id=>({request:'网站操作',auth:'注册与登录',admin:'管理员操作',provider:'AI 接口',task:'任务状态',system:'系统运行'}[id]||id);
const actions={application_started:'服务启动',application_stopped:'服务停止',task_sync_failed:'任务同步失败',task_sync_recovered:'任务同步恢复',request_exception:'内部异常',stream_error:'文件传输异常',generation_status:'音频任务状态',cover_status:'封面任务状态',text_completion:'AI 文本调用',task_submit:'提交生成',task_query:'查询任务',reference_upload:'上传参考素材',service_request:'AI 服务请求',login:'登录成功',password_set:'设置密码',invitation_created:'生成邀请',account_updated:'修改账号',diagnostic_export:'导出诊断',access_denied:'后台访问被拒绝',operations_read:'后台查询失败'};
Object.assign(actions,{register:'用户注册',logout:'退出登录',storage_repair:'启动存储修复',assistant_post:'AI 写作请求',generations_post:'音频任务操作',generations_delete:'清理音频任务',covers_post:'生成封面',covers_put:'上传封面',assets_put:'上传素材',assets_delete:'清理素材',state_put:'保存工作区资料',account_put:'修改个人资料',releases_post:'发布作品',releases_delete:'取消发布',auth_post:'账号验证请求',health_get:'健康检查'});
export const empty=(title,note='')=>'<div class="empty-state"><strong>'+esc(title)+'</strong>'+esc(note)+'</div>';
export function serviceRow(name,status,message,detail=''){return '<div class="health-item"><span class="health-name">'+esc(name)+'</span>'+badge(status==='ok'?'正常':status==='warn'?'需关注':status==='error'?'异常':'未接入',status==='ok'?'good':status==='warn'?'warn':status==='error'?'error':'muted')+'<span class="health-message">'+esc(message)+(detail?'<br>'+esc(detail):'')+'</span></div>';}
export function renderTasks(items,compact=false){
 if(!items.length)return empty(compact?'这个范围内没有需要关注的任务':'这个范围内没有任务记录',compact?'失败、提交待核对和备用封面会显示在这里。':'可调整时间、用户或任务状态。');
 return '<div class="table-wrap"><table><thead><tr><th>作品 / 任务</th><th>用户</th><th>模型 / 渠道</th><th>状态</th><th>最近更新（北京）</th></tr></thead><tbody>'+items.map(task=>'<tr><td><strong class="cell-main">'+esc(task.title)+'</strong><span class="cell-sub">'+esc(task.kind==='cover'?'封面':'音频')+' · '+esc(task.id)+'</span>'+(task.error?'<span class="cell-sub">'+esc(task.error)+'</span>':'')+(!compact&&task.taskId?'<span class="cell-sub">服务任务：'+esc(task.taskId)+'</span>':'')+'</td><td><span class="cell-main">'+esc(task.actorName||'未知用户')+'</span><span class="cell-sub">'+esc(task.actorEmail)+'</span></td><td><span class="cell-main">'+esc(task.model||'—')+'</span><span class="cell-sub">'+esc(providerName(task.provider))+'</span></td><td>'+statusBadge(task.status)+'</td><td class="cell-time">'+esc(date(task.updatedAt))+'</td></tr>').join('')+'</tbody></table></div>';
}
export function renderEvents(items){
 if(!items.length)return empty('这个范围内没有运行记录','可调整时间、级别或类型；日志从本次接入后开始保存。');
 return '<div class="table-wrap"><table><thead><tr><th>时间（北京）</th><th>级别 / 类型</th><th>内容</th><th>用户 / 服务</th></tr></thead><tbody>'+items.map(event=>'<tr><td class="cell-time">'+esc(date(event.last_seen_at))+(event.repeat_count>1?'<span class="cell-sub">合并 '+number(event.repeat_count)+' 次</span>':'')+'</td><td>'+badge({info:'正常',warn:'警告',error:'错误'}[event.level],{info:'good',warn:'warn',error:'error'}[event.level])+'<span class="cell-sub">'+esc(categoryName(event.category))+'</span></td><td><strong class="cell-main">'+esc(actions[event.action]||event.action)+'</strong><div class="event-message">'+esc(event.message)+'</div><details class="event-detail"><summary>诊断信息</summary><p>事件 #'+number(event.id)+(event.status!==null?' · HTTP '+number(event.status):'')+(event.code?' · '+esc(event.code):'')+(event.duration_ms!==null?' · '+number(event.duration_ms)+' ms':'')+'</p>'+(event.resource_id?'<p>关联任务 / 账号：'+esc(event.resource_id)+'</p>':'')+(event.request_id?'<p>请求编号：'+esc(event.request_id)+'</p>':'')+(event.prompt_tokens!==null?'<p>输入 / 输出 Token：'+number(event.prompt_tokens)+' / '+number(event.completion_tokens)+'</p>':'')+'</details></td><td><span class="cell-main">'+esc(event.actor_name||'系统 / 未登录')+'</span><span class="cell-sub">'+esc(event.provider?providerName(event.provider):event.actor_email||'')+'</span></td></tr>').join('')+'</tbody></table></div>';
}
